/bin/bash -lc "node --input-type=module <<'JS'
import { chromium, expect } from '@playwright/test';
const browser = await chromium.launch();
const page=await browser.newPage({viewport:{width:1440,height:1100}});
await page.goto('http://localhost:3000/books/the-creative-act');
await page.waitForLoadState('networkidle');
await page.screenshot({path:'/tmp/folio-detail.png',fullPage:true});
await page.goto('http://localhost:3000');
await page.getByRole('button',{name:'Add a book',exact:true}).click();
await expect(page.getByRole('dialog')).toBeVisible();
await page.screenshot({path:'/tmp/folio-add.png',fullPage:true});
await page.keyboard.press('Escape');
await expect(page.getByRole('dialog')).not.toBeVisible();
await page.getByRole('button',{name:'Reading 3',exact:true}).click();
await expect(page.locator('.reading-card')).toHaveCount(3);
await expect(page.locator('.finished-card')).toHaveCount(0);
await page.getByLabel('Sort books').selectOption('title');
await expect(page.locator('.reading-card h3').first()).toHaveText('A Psalm for the Wild-Built');
await page.getByRole('button',{name:'Finished 2',exact:true}).click();
await expect(page.locator('.finished-card')).toHaveCount(2);
await expect(page.locator('.reading-card')).toHaveCount(0);
console.log('Detail and form screenshots saved; filters, alphabetical sorting, and Escape-to-close passed.');
await browser.close();
JS"
